package com.sivion.api.finance.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="finance_expenses") public class Expense { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tenant_id",nullable=false) Long tenantId; @Column(nullable=false) String expenseNumber; @Column(nullable=false) String category; @Column(nullable=false) String description; @Column(nullable=false) BigDecimal amount; @Column(nullable=false) String status="SUBMITTED"; @Column(nullable=false) Instant expenseDate=Instant.now(); public Long getId(){return id;} public Long getTenantId(){return tenantId;} public void setTenantId(Long v){tenantId=v;} public String getExpenseNumber(){return expenseNumber;} public void setExpenseNumber(String v){expenseNumber=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getExpenseDate(){return expenseDate;} }
